import React from 'react';
import { Link, useParams } from 'react-router-dom';
import { products } from '../data/products';

const ProductDetails = () => {
	const { productId } = useParams();
	const product = products.find((item) => item.id === productId);

	if (!product) {
		return (
			<div className="products-page">
				<div className="products-header">
					<h1>Product Not Found</h1>
					<p>This product does not exist or was removed.</p>
					<Link className="products-view-btn" to="/products">
						Back To Products
					</Link>
				</div>
			</div>
		);
	}

	return (
		<div className="products-page">
			<div className="product-detail-layout">
				<div className="product-detail-image-wrap">
					<img src={product.image} alt={product.name} className="product-detail-image" />
				</div>

				<div className="product-detail-content">
					<p className="products-category">{product.category}</p>
					<h1>{product.name}</h1>
					<div className="products-pricing">
						<span className="products-current">{product.price}</span>
						<span className="products-original">{product.originalPrice}</span>
					</div>
					<p className="product-detail-rating">Rating: {product.rating} / 5</p>
					<p className="product-detail-description">{product.description}</p>

					<div className="product-detail-actions">
						<Link className="products-view-btn" to="/products">
							View All Products
						</Link>
						<Link className="auth-back-link" to="/">
							Back To Home
						</Link>
					</div>
				</div>
			</div>
		</div>
	);
};

export default ProductDetails;
